-- Removes every sample shop, item, photo row and owner account added by sample-shops.sql.
-- Generated by scripts/samples/build.py. Real shops are untouched.
begin;
delete from public.reports where shop_id in (select id from public.shops where owner_id in (select id from auth.users where email like '%@sample.doyouwannathrift.invalid'))
  or product_id in (select id from public.products where shop_id in (select id from public.shops where owner_id in (select id from auth.users where email like '%@sample.doyouwannathrift.invalid')));
delete from public.products where shop_id in (select id from public.shops where owner_id in (select id from auth.users where email like '%@sample.doyouwannathrift.invalid'));
delete from auth.users where email like '%@sample.doyouwannathrift.invalid';
commit;
